<script setup lang="ts">
import { computed,defineAsyncComponent,onMounted,onUnmounted,ref } from 'vue'
import { Building2,ChartNoAxesCombined,ShieldCheck,Radio,ArrowUpRight,ArrowDownRight,Users,Activity,FlaskConical,ChevronRight,Rotate3D,MousePointer2,Maximize2,Wallet,Layers3,Newspaper,Download } from 'lucide-vue-next'
const Office=defineAsyncComponent(()=>import('./components/Office.vue'))
import { useCompany } from './store'
import CompanyControl from './components/CompanyControl.vue'
import { agentSummary, operationLabels, eventLabels } from './presentation'
import { money,price,clock,stateLabels,strategyLabels,type Backtest } from './types'
const diagnostics=ref(false)
const company=useCompany(), view=ref('office'),tab=ref('positions'),symbol=ref(''),split=ref('test'),running=ref(false),backtestError=ref(''),result=ref<Backtest|null>(null)
const titles:Record<string,string>={office:'Seu escritório, em movimento.',operations:'Cada operação, rastreável.',research:'Estratégias sob investigação.'}
const totalPnl=computed(()=>Number(company.data?.account?.realized_pnl??0)+Number(company.data?.account?.unrealized_pnl??0))
const selectedEvents=computed(()=>company.data?.events.filter(e=>e.producer===company.selected).slice(0,6)??[])
const stale=computed(()=>company.data?.positions.some(p=>p.stale))
const agents=computed(()=>company.data?.agents??[])
const roomNames:Record<string,string>={market:'Inteligência de Mercado',technical:'Análise Técnica',news:'Notícias e IA',committee:'Comitê de Trading',risk:'Gestão de Risco',audit:'Diretoria',execution:'Trading Floor',cafe:'Área de descanso'}
const teamAgents=computed(()=>agents.value.filter(a=>(a.id.startsWith('analyst_')?'floor':a.room==='audit'?'board':a.room==='execution'?'floor':a.room)===company.selectedTeam))
const selectedTeamName=computed(()=>company.selectedTeam?roomNames[company.selectedTeam]??'Trading Floor':'')
const selectedTeamPnl=computed(()=>teamAgents.value.reduce((sum,a)=>sum+Number(company.data?.teams.find(t=>t.strategy.toLowerCase()===a.id.toLowerCase())?.realized_pnl??0),0))
const selectedAgentPnl=computed(()=>Number(company.data?.teams.find(t=>t.strategy.toLowerCase()===company.agent?.id.toLowerCase())?.realized_pnl??0))
const curve=computed(()=>{const values=company.data?.equity_history.map(p=>Number(p.equity))??[];return points(values)})
function points(values:number[]){if(values.length<2)return '';const min=Math.min(...values),max=Math.max(...values);return values.map((v,i)=>`${i/(values.length-1)*400},${75-(v-min)/(max-min||1)*60}`).join(' ')}
const backtestCurve=computed(()=>points((result.value?.report.equity_curve as number[])??[]))
const metrics:Record<string,string>={realized_pnl:'PnL realizado',unrealized_pnl:'PnL não realizado',return_pct:'Retorno (%)',buy_hold_return_pct:'Buy & hold (%)',sma_reference_return_pct:'Referência SMA (%)',fees:'Taxas',slippage_cost:'Spread + slippage',trades:'Operações encerradas',win_rate:'Taxa de acerto (0–1)',profit_factor:'Profit factor',expectancy:'Expectativa / operação',max_drawdown:'Drawdown máximo (0–1)',exposure:'Exposição (0–1)',sharpe:'Sharpe anualizado'}
async function runBacktest(){running.value=true;backtestError.value='';try{const response=await fetch('/api/v1/backtests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({symbol:symbol.value||company.data?.ranking[0]?.symbol,split:split.value})});const value=await response.json();if(!response.ok)throw new Error(value.error);result.value=value;company.refresh()}catch(e){backtestError.value=String(e)}finally{running.value=false}}
function download(){if(!result.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(result.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`backtest-${result.value.symbol}.json`;a.click();URL.revokeObjectURL(url)}
onMounted(company.start);onUnmounted(company.stop)
</script>
<template>
  <div class="shell">
    <aside class="rail"><a class="brand" href="#" aria-label="Crypto Trading Company"><Layers3 :size="25"/></a><div class="rail-divider"/><button :class="{active:view==='office'}" @click="view='office'" title="Escritório" aria-label="Escritório"><Building2/></button><button :class="{active:view==='operations'}" @click="view='operations'" title="Operações" aria-label="Operações"><ChartNoAxesCombined/></button><button :class="{active:view==='research'}" @click="view='research'" title="Pesquisa e backtesting" aria-label="Pesquisa"><FlaskConical/></button><div class="rail-bottom"><ShieldCheck/><span>SIM</span></div></aside>
    <div class="workspace">
      <header class="topbar"><div class="wordmark">CRYPTO TRADING <span>COMPANY</span><small>OPERAÇÕES / 3D</small></div><div class="top-meta"><span class="simulation"><ShieldCheck :size="14"/> OPERAÇÕES FICTÍCIAS</span><span class="connection" :class="{disconnected:!company.connected}"><i/>{{company.connected?'Ao vivo':'Reconectando'}}</span><div class="avatar">CT</div></div></header>
      <main>
        <section class="page-heading"><div><div class="eyebrow">CENTRAL DE GESTÃO <span>/</span> {{view==='research'?'PESQUISA':'OPERAÇÕES AO VIVO'}}</div><h1>{{titles[view]}}</h1><p>Dados reais. Equipes autônomas. Capital exclusivamente fictício.</p></div><div class="online-pill"><Users :size="17"/><strong>{{company.online}}</strong> agentes online</div></section>
        <div v-if="company.error" class="notice">{{company.error}}. O estado exibido pode estar desatualizado.</div>
        <div v-if="stale" class="notice">Há posições com cotação desatualizada. Novas compras são bloqueadas pelo risco.</div>
        <CompanyControl/><section class="metrics">
          <article><div class="metric-label"><Wallet :size="16"/> Patrimônio simulado <span>USDT</span></div><div class="metric-value">{{company.data?.account?money(company.data.account.equity):'—'}}</div><div class="metric-foot">Saldo disponível <strong>{{money(company.data?.account?.available ?? company.data?.account?.cash)}}</strong></div></article>
          <article><div class="metric-label"><ChartNoAxesCombined :size="16"/> Resultado total <span>SIMULADO</span></div><div class="metric-value" :class="totalPnl>=0?'positive':'negative'">{{totalPnl>=0?'+':''}}{{money(totalPnl)}}<ArrowUpRight v-if="totalPnl>=0" :size="23"/><ArrowDownRight v-else :size="23"/></div><div class="metric-foot">Realizado {{money(company.data?.account?.realized_pnl)}} · aberto {{money(company.data?.account?.unrealized_pnl)}}</div></article>
          <article><div class="metric-label"><Activity :size="16"/> Posições abertas <span>SPOT</span></div><div class="metric-value">{{company.data?.positions.length??0}}<small>/ {{company.data?.account?.limits.max_positions??6}}</small></div><div class="metric-foot">Exposição <strong>{{money(company.data?.account?.exposure)}} USDT</strong></div></article>
          <article><div class="metric-label"><ShieldCheck :size="16"/> Controle de risco <span>ATIVO</span></div><div class="metric-value">{{(Number(company.data?.account?.drawdown??0)*100).toFixed(2)}}<small>% DD</small></div><div class="metric-foot">Taxas acumuladas <strong>{{money(company.data?.account?.fees)}} USDT</strong></div></article>
        </section>
        <section v-if="view==='office'" class="office-grid">
          <div class="office-panel"><div class="panel-title"><div><span class="live-dot"/>SALÃO DE OPERAÇÕES <span class="muted">/ escritório 3D</span></div><span class="small-tag">8 DEPARTAMENTOS · {{agents.length}} AGENTES LÓGICOS</span></div><Office/><div class="scene-hud"><span><Rotate3D :size="14"/> Arraste para orbitar</span><span><Maximize2 :size="14"/> Scroll para zoom</span><span><MousePointer2 :size="14"/> Clique em agente ou departamento</span></div><div class="scene-label"><i/>ESTADO DO BACKEND<span>SIMULAÇÃO</span></div></div>
          <aside class="side-column">
            <section v-if="company.selectedTeam" class="team-detail"><div class="panel-title">DEPARTAMENTO<button class="close" aria-label="Fechar equipe" @click="company.selectedTeam=null">×</button></div><h2>{{selectedTeamName}}</h2><div class="team-pnl" :class="selectedTeamPnl>=0?'positive':'negative'">{{selectedTeamPnl>=0?'+':''}}{{money(selectedTeamPnl)}} USDT <small>P&amp;L realizado atribuído pelas estratégias</small></div><div class="mini-heading">{{teamAgents.length}} INTEGRANTES / ESTADO DO BACKEND</div><div class="agent-list"><button v-for="a in teamAgents" :key="a.id" @click="company.selectedTeam=null;company.selected=a.id"><span class="mini-avatar" :class="a.room">{{a.name[0]}}</span><div><strong>{{a.name}}</strong><small>{{a.role}}</small></div><i :class="a.online?a.state:'offline'"/></button><p v-if="!teamAgents.length" class="empty">Departamento aguardando novos agentes.</p></div><div class="table-footer">Sala selecionada · câmera focada no departamento</div></section><section v-else-if="company.agent" class="agent-detail"><div class="panel-title">AGENTE SELECIONADO<button class="close" aria-label="Fechar agente" @click="company.selected=null">×</button></div><div class="person-header"><div class="person-avatar">{{company.agent.name[0]}}</div><div><h2>{{company.agent.name}}</h2><p>{{company.agent.role}}</p></div></div><span class="state-chip" :class="company.agent.state">{{company.agent.online?stateLabels[company.agent.state]:'Sem conexão'}}</span><div class="detail-grid"><span>Atividades <b>{{company.agent.tasks}}</b></span><span>Último contato <b>{{clock(company.agent.heartbeat)}}</b></span></div><div v-if="company.data?.teams.some(t=>t.strategy.toLowerCase()===company.agent?.id.toLowerCase())" class="team-pnl" :class="selectedAgentPnl>=0?'positive':'negative'">{{selectedAgentPnl>=0?'+':''}}{{money(selectedAgentPnl)}} USDT <small>P&amp;L realizado desta estratégia na simulação</small></div><p class="agent-description">{{agentSummary(company.agent)}}</p><div class="mini-heading">ÚLTIMOS EVENTOS</div><div class="mini-event" v-for="e in selectedEvents" :key="e.event_id"><span>{{eventLabels[e.payload.kind??'']??'Acontecimento registrado'}}</span><time>{{clock(e.occurred_at)}}</time></div></section>
            <section v-else class="team-overview"><div class="panel-title">A EMPRESA AGORA<Users :size="16"/></div><h2>Inteligência em equipe.</h2><p>Cada personagem representa uma função lógica do backend. Selecione alguém para explorar suas decisões.</p><div class="agent-list"><button v-for="a in agents" :key="a.id" @click="company.selected=a.id"><span class="mini-avatar" :class="a.room">{{a.name[0]}}</span><div><strong>{{a.name}}</strong><small>{{a.role}}</small></div><i :class="a.online?a.state:'offline'"/></button><p v-if="!agents.length" class="empty">Aguardando registro dos serviços…</p></div></section>
          </aside>
        </section>
        <section v-if="view==='research'" class="research-grid">
          <article class="panel backtest"><div class="panel-title"><span><FlaskConical :size="17"/> LABORATÓRIO DE BACKTEST</span><span class="small-tag">SEM LOOK-AHEAD</span></div><h2>Teste a hipótese, não a sorte.</h2><p>Histórico real de 1 minuto. Decisão no fechamento, execução na abertura seguinte. Parâmetros fixos; treino 60%, validação 20%, teste 20%.</p><form @submit.prevent="runBacktest"><label>Ativo<select v-model="symbol"><option value="">Primeiro ativo do ranking</option><option v-for="r in company.data?.ranking" :key="r.symbol">{{r.symbol}}</option></select></label><label>Amostra<select v-model="split"><option value="test">Teste fora da amostra</option><option value="validation">Validação</option><option value="train">Treinamento</option></select></label><button class="primary" :disabled="running||!company.data?.ranking.length">{{running?'Calculando…':'Executar backtest'}}<ArrowUpRight :size="16"/></button></form><p v-if="backtestError" class="negative" role="alert">{{backtestError}}</p><div v-if="result"><div class="report-heading"><h3>{{result.symbol}} / {{result.report.split}}</h3><button class="text-button" @click="download"><Download :size="16"/>JSON</button></div><svg class="equity-chart" viewBox="0 0 400 90" role="img" aria-label="Curva de patrimônio do backtest"><polyline :points="backtestCurve" fill="none" stroke="#447d62" stroke-width="2"/></svg><div class="backtest-metrics"><div v-for="(label,key) in metrics" :key="key"><span>{{label}}</span><b>{{result.report[key]===null?'Indefinido':money(result.report[key])}}</b></div></div><p class="footnote">{{result.report.dataset_size}} candles · hash {{result.dataset_hash.slice(0,16)}}… · Resultado simulado, sem promessa de retorno. Sharpe em amostra curta tem baixa estabilidade.</p></div><div v-else class="empty">Selecione um ativo com histórico coletado para iniciar.</div></article>
          <article class="panel"><div class="panel-title"><span><Newspaper :size="17"/> INTELIGÊNCIA DE NOTÍCIAS</span></div><div v-for="n in company.data?.news" :key="n.id" class="news-item"><div class="news-meta">{{n.source}}<span :class="n.sentiment>=0?'positive':'negative'">{{n.sentiment.toFixed(2)}}</span></div><a :href="n.url" target="_blank" rel="noopener noreferrer">{{n.title}} <ArrowUpRight :size="14"/></a><p>{{n.assets.join(' · ')||'Mercado geral'}} · {{n.analysis.method}}</p></div><div v-if="!company.data?.news.length" class="empty">Nenhuma notícia coletada. Confira o agente Lia e a configuração das fontes.</div></article>
        </section>
        <section v-if="view!=='research'" class="lower-grid">
          <article class="panel activity-panel"><div class="tabs"><button :class="{active:tab==='positions'}" @click="tab='positions'">Posições <span>{{company.data?.positions.length??0}}</span></button><button :class="{active:tab==='fills'}" @click="tab='fills'">Operações</button><button :class="{active:tab==='decisions'}" @click="tab='decisions'">Decisões</button><button :class="{active:tab==='risk'}" @click="tab='risk'">Risco</button></div><div class="table-wrap">
            <table v-if="tab==='positions'"><thead><tr><th>ATIVO</th><th>QUANTIDADE</th><th>PREÇO MÉDIO</th><th>VALOR ATUAL</th><th>PNL ABERTO</th></tr></thead><tbody><tr v-for="p in company.data?.positions" :key="p.symbol"><td><b>{{p.symbol}}</b><small>{{strategyLabels[p.strategy]??p.strategy}}</small></td><td>{{price(p.quantity)}}</td><td>{{price(p.average_price)}}</td><td>{{money(p.value)}} <span v-if="p.stale" class="negative">atrasado</span></td><td :class="Number(p.unrealized_pnl)>=0?'positive':'negative'">{{money(p.unrealized_pnl)}}</td></tr></tbody></table>
            <table v-if="tab==='fills'"><thead><tr><th>HORÁRIO</th><th>ATIVO / LADO</th><th>QUANTIDADE</th><th>PREÇO</th><th>TAXA</th><th>PNL REALIZADO</th></tr></thead><tbody><tr v-for="f in company.data?.fills" :key="f.id"><td>{{clock(f.created_at)}}</td><td><b>{{f.symbol}}</b><span class="trade-side" :class="f.side">{{operationLabels[f.side]??f.side}}</span></td><td>{{price(f.quantity)}}</td><td>{{price(f.price)}}</td><td>{{money(f.fee)}}</td><td :class="Number(f.realized_pnl)>=0?'positive':'negative'">{{money(f.realized_pnl)}}</td></tr></tbody></table>
            <table v-if="tab==='decisions'"><thead><tr><th>HORÁRIO</th><th>ATIVO</th><th>DECISÃO</th><th>SCORE</th><th>JUSTIFICATIVA</th></tr></thead><tbody><tr v-for="d in company.data?.decisions" :key="d.id"><td>{{clock(d.created_at)}}</td><td><b>{{d.symbol}}</b></td><td><span class="trade-side" :class="d.action">{{operationLabels[d.action]??d.action}}</span></td><td>{{d.score.toFixed(3)}}</td><td class="reason"><details><summary>{{d.detail.analysis.reason}}</summary><p v-for="s in d.detail.analysis.signals" :key="s.strategy">{{strategyLabels[s.strategy]}}: {{s.score.toFixed(3)}} — {{s.reason}}</p></details></td></tr></tbody></table>
            <table v-if="tab==='risk'"><thead><tr><th>HORÁRIO</th><th>ATIVO</th><th>ESTADO</th><th>JUSTIFICATIVA</th></tr></thead><tbody><tr v-for="o in company.data?.orders" :key="o.id"><td>{{clock(o.created_at)}}</td><td><b>{{o.symbol}}</b> {{operationLabels[o.side]??o.side}}</td><td><span class="trade-side" :class="o.status">{{operationLabels[o.status]??o.status}}</span></td><td class="reason">{{o.risk_reason||o.reason}}<p v-if="o.risk_snapshot?.sizing_explanation">{{o.risk_snapshot.sizing_explanation}}</p></td></tr></tbody></table>
            <div v-if="(tab==='positions'&&!company.data?.positions.length)||(tab==='fills'&&!company.data?.fills.length)||(tab==='decisions'&&!company.data?.decisions.length)" class="empty"><ShieldCheck :size="26"/><strong>{{tab==='positions'?'Nenhuma posição aberta':'Aguardando o primeiro ciclo'}}</strong><span>Operações surgem apenas após sinais reais e aprovação do risco.</span></div>
          </div><div class="table-footer">{{tab==='fills'?'Últimas 100 operações fictícias':'Projeção persistida do backend'}}<span>USDT · sem fundos reais</span></div></article>
          <article class="panel ranking"><div class="panel-title"><span>RADAR DE OPORTUNIDADES</span><Radio :size="17"/></div><div class="ranking-header"><span>ATIVO / VOLUME 24H</span><span>VARIAÇÃO / SCORE</span></div><div v-for="(r,index) in company.data?.ranking.slice(0,7)" :key="r.symbol" class="ranking-row"><span class="rank-index">{{String(index+1).padStart(2,'0')}}</span><div class="coin-avatar">{{r.symbol[0]}}</div><div class="rank-name"><strong>{{r.symbol.replace('USDT','')}}<small>/ USDT</small></strong><small>${{(r.volume/1e6).toFixed(1)}}M · spread {{r.spread_bps.toFixed(1)}} bps</small></div><div class="rank-score"><strong :class="r.change>=0?'positive':'negative'">{{r.change>=0?'+':''}}{{r.change.toFixed(2)}}%</strong><small>{{r.score.toFixed(1)}} pts</small></div></div><div v-if="!company.data?.ranking.length" class="empty">Aguardando dados públicos da Binance.</div><div class="table-footer">Volume, liquidez, volatilidade e tendência<ChevronRight :size="14"/></div></article>
        </section>
        <section class="bottom-grid"><article class="panel"><div class="panel-title">PERFORMANCE DOS ROBÔS<span class="small-tag">ATRIBUIÇÃO AO ESPECIALISTA LÍDER</span></div><div class="robot-ranking"><div v-for="(team,index) in company.data?.teams" :key="team.strategy"><span class="rank-index">{{index+1}}</span><strong>{{strategyLabels[team.strategy]??team.strategy}}</strong><span>{{team.closed}} encerradas · {{team.closed?(team.wins/team.closed*100).toFixed(0):'—'}}% acerto</span><b :class="Number(team.realized_pnl)>=0?'positive':'negative'">{{money(team.realized_pnl)}} USDT</b></div><p v-if="!company.data?.teams.length" class="empty">O ranking será formado a partir das operações executadas.</p></div></article><article class="panel"><div class="panel-title">PATRIMÔNIO AO LONGO DO TEMPO<Activity :size="17"/></div><svg v-if="curve" class="equity-chart" viewBox="0 0 400 90" role="img" aria-label="Histórico real do patrimônio simulado"><polyline :points="curve" fill="none" stroke="#447d62" stroke-width="2"/></svg><p v-else class="empty">Coletando observações de patrimônio.</p></article></section>
        <section v-if="diagnostics" class="panel"><div class="panel-title">DIAGNÓSTICO TÉCNICO</div><pre>{{JSON.stringify(company.data,null,2)}}</pre></section><footer><button class="text-button" @click="diagnostics=!diagnostics">{{diagnostics?'Fechar diagnóstico':'Área técnica'}}</button><span><ShieldCheck :size="14"/> Ambiente simulado. Resultados não representam lucros reais.</span><span>DADOS PÚBLICOS BINANCE · CTC / MVP</span></footer>
      </main>
    </div>
  </div>
</template>
